cat > tests/test_contacts.py <<'EOF'
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


def make(last, first, section="A", email="x@example.com"):
    return Student("1", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([
            make("Zed", "Amy", "B", "amy@example.com"),
            make("Abe", "Bo", "A", "bo@example.com"),
        ])
        self.assertEqual(rows, [
            "Abe, Bo             A        bo@example.com",
            "Zed, Amy            B        amy@example.com",
        ])

    def test_missing_email_names_the_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([make("Abe", "Bo", email=None)])
        self.assertIn("Abe, Bo", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
